<?php use App\Core\DB;if($module!=='products'||!in_array($group,['Images','Specifications'],true))return;$child=$group==='Images'?'product_images':'product_specifications';?>
<div class="related-editor"><h3><?=$group==='Images'?'Additional product images':'Product specifications'?></h3><?php if(!$id):?><p class="muted">Save the product first, then add <?=$group==='Images'?'additional images':'specifications'?> here.</p><?php else:$related=DB::all('SELECT * FROM `'.$child.'` WHERE product_id=? ORDER BY sort_order,id',[$id]);?><p class="field-help">Changes to these items take effect immediately on a published product.</p><?php if($related):?><div class="related-item-grid"><?php foreach($related as $item):?><a class="related-item" href="<?=e(cms_url('/admin/'.$child.'/'.$item['id']))?>"><?php if($group==='Images'):?><?=media_img($item['image_id'],$item['title'])?><?php endif?><strong><?=e($item['title'])?></strong><?php if($group==='Specifications'):?><span><?=e($item['value'])?></span><?php endif?><small>Edit →</small></a><?php endforeach?></div><?php endif?><div class="actions"><a class="button secondary" href="<?=e(cms_url('/admin/'.$child.'/new?product_id='.$id))?>">＋ Add <?=$group==='Images'?'image':'specification'?></a><a class="text-link" href="<?=e(cms_url('/admin/'.$child.'?product_id='.$id))?>">Manage <?=$group==='Images'?'all images / bulk upload':'all specifications'?> →</a></div><?php endif?></div>
